using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using Object=UnityEngine.Object;
[InitializeOnLoad]public static class GridShiftV9Checks {
 static GridShiftV9Checks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("GS.V9.Test",false)){SessionState.SetBool("GS.V9.Test",false);var go=new GameObject("V9Tests");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftV9Runner>();}};}
 public static void Run(){if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");SessionState.SetBool("GS.V9.Test",true);EditorApplication.isPlaying=true;}
}
public sealed class GridShiftV9Runner:MonoBehaviour {
 readonly StringBuilder report=new StringBuilder();string oldPrefix;
 void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);File.WriteAllText("Docs/Validacao9/runtime.txt",report.ToString());if(!ok)throw new Exception(label);}
 IEnumerator Start(){Application.runInBackground=true;var run=Run();bool ok=true;while(true){bool more;object value=null;try{more=run.MoveNext();if(more)value=run.Current;}catch(Exception e){ok=false;report.AppendLine(e.ToString());break;}if(!more)break;yield return value;}Time.timeScale=1;GridShiftControls.Prefix=oldPrefix??"GS.Keys.";GridShiftControls.Reload();DeliverySaveStore.OverridePath=null;report.AppendLine("RESULT "+(ok?"SUCCESS":"FAILURE"));File.WriteAllText("Docs/Validacao9/runtime.txt",report.ToString());EditorApplication.isPlaying=false;}
 Button Find(Transform root,string name)=>root.GetComponentsInChildren<Button>(true).First(b=>b.name==name);
 IEnumerator Run(){yield return new WaitForSecondsRealtime(4);var menu=Object.FindFirstObjectByType<GridShiftMainMenu>();Check(menu!=null,"menu principal instalado");Check(Find(menu.transform,"Novo Jogo").image.sprite==GridShiftUITheme.Get("Botao_Amarelo_Normal"),"botão principal usa sprite real");Check(Find(menu.transform,"Controles").onClick.GetPersistentEventCount()==0,"eventos runtime preservados");Find(menu.transform,"Controles").onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(GridShiftOperationsUI.Instance.Current=="controls","controles acessíveis no menu principal");GridShiftOperationsUI.Instance.Close();Find(menu.transform,"Créditos").onClick.Invoke();Check(menu.GetComponentsInChildren<TMPro.TMP_Text>().Any(t=>t.text.Contains("Anna Clara Lara Pereira")),"créditos incluem equipe SENAI");Find(menu.transform.Find("Menu/Credits"),"Voltar").onClick.Invoke();
 var pause=PauseMenu.Instance;pause.OpenSettingsFromMainMenu(()=>{});yield return new WaitForSecondsRealtime(.3f);Check(Time.timeScale==0&&pause.SettingsOpen,"configurações animam com tempo pausado");foreach(var slider in pause.GetComponentsInChildren<Slider>(true)){float before=slider.value;slider.SetValueWithoutNotify(slider.minValue);Canvas.ForceUpdateCanvases();Check(slider.fillRect.anchorMax.x<=.01f,slider.name+" preenchimento mínimo real");slider.SetValueWithoutNotify(slider.maxValue);Canvas.ForceUpdateCanvases();Check(slider.fillRect.anchorMax.x>=.99f,slider.name+" preenchimento máximo real");slider.SetValueWithoutNotify(before);Check(slider.handleRect.GetComponent<Image>().sprite==GridShiftUITheme.Get("Slider_Puxador"),slider.name+" puxador personalizado");}
 Check(pause.GetComponentsInChildren<Toggle>(true).Length>=3,"toggles funcionais");pause.Close();yield return new WaitForSecondsRealtime(.3f);Check(Time.timeScale==1,"fechar configurações restaura tempo");oldPrefix=GridShiftControls.Prefix;GridShiftControls.Prefix="GS.V9.Test.Keys.";GridShiftControls.Reset();Check(!GridShiftControls.Rebind(GSAction.Forward,UnityEngine.InputSystem.Key.S,out _),"conflito real de remapeamento recusado");Check(GridShiftControls.Rebind(GSAction.Forward,UnityEngine.InputSystem.Key.K,out _),"remapeamento real aceita tecla livre");GridShiftControls.Reset();Check(GridShiftControls.Binding(GSAction.Forward)==UnityEngine.InputSystem.Key.W,"restaurar padrão real");GridShiftControls.Prefix=oldPrefix;GridShiftControls.Reload();
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1600,900),new Vector2Int(1920,1080),new Vector2Int(2560,1440)})GridShiftV9Capture.Save("menu",size.x,size.y);pause.OpenSettingsFromMainMenu(()=>{});yield return new WaitForSecondsRealtime(.3f);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1600,900),new Vector2Int(1920,1080),new Vector2Int(2560,1440)})GridShiftV9Capture.Save("settings",size.x,size.y);for(int tab=0;tab<6;tab++){string[] labels={"Gráficos","Áudio","Jogabilidade","Desempenho","Controles","Interface"};Find(pause.transform,labels[tab]).onClick.Invoke();Canvas.ForceUpdateCanvases();GridShiftV9Capture.Save("settings-"+tab,1920,1080);}pause.Close();yield return new WaitForSecondsRealtime(.3f);if(SessionState.GetBool("GS.V9.Visual",false)){SessionState.SetBool("GS.V9.Visual",false);yield break;}DeliverySaveStore.OverridePath=Path.GetFullPath("Temp/v9-test-save.json");menu.StartGame(false);float until=Time.realtimeSinceStartup+60;while(SceneManager.GetActiveScene().name!="SampleScene"&&Time.realtimeSinceStartup<until)yield return null;yield return new WaitForSecondsRealtime(3);Check(SceneManager.GetActiveScene().name=="SampleScene","novo jogo carrega cidade real");var player=Object.FindFirstObjectByType<PlayerMovement>();var ui=GridShiftOperationsUI.Instance;var manager=DeliveryManager.Instance;Check(player!=null&&manager!=null,"jogador e entregas ativos após loading");ui.Open("map");yield return new WaitForSecondsRealtime(.3f);Check(ui.Current=="map"&&player.ControlsBlocked,"mapa bloqueia controle do jogador");Find(ui.transform,"+").onClick.Invoke();Find(ui.transform,"−").onClick.Invoke();GridShiftV9Capture.Save("map",1920,1080);ui.Close();Check(!player.ControlsBlocked,"fechar mapa restaura controles");pause.Open();yield return new WaitForSecondsRealtime(.3f);GridShiftV9Capture.Save("pause",1920,1080);pause.Close();ui.Open("upgrades");yield return new WaitForSecondsRealtime(.3f);GridShiftV9Capture.Save("upgrades",1920,1080);ui.Close();var hud=player.CameraTransform.GetComponentsInChildren<Canvas>(true).FirstOrDefault(c=>c.name=="DeliveryHUD");Check(hud!=null&&hud.renderMode==RenderMode.WorldSpace,"HUD de entregas preserva canvas 3D");Check(manager.Accept(manager.Offers().First().id,out var error),"aceitar contrato real: "+error);Check(manager.GetComponent<DeliveryPersistence>().Save(),"salvar entrega em arquivo isolado");Check(DeliverySaveStore.Read(out var saved)&&saved!=null,"reler salvamento real");var identity=manager.GetInstanceID();WorldSession.Instance.RequestTransition("Office",player.transform);until=Time.realtimeSinceStartup+60;while((WorldSession.Instance.Busy||SceneManager.GetActiveScene().name!="Office")&&Time.realtimeSinceStartup<until)yield return null;Check(SceneManager.GetActiveScene().name=="Office"&&!WorldSession.Instance.Busy,"transição real Office conclui");Check(DeliveryManager.Instance.GetInstanceID()==identity,"Office preserva simulação e pedidos");var office=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="Office");WorldSession.Instance.RequestTransition("SampleScene",office.transform);until=Time.realtimeSinceStartup+60;while(WorldSession.Instance.Busy&&Time.realtimeSinceStartup<until)yield return null;Check(SceneManager.GetActiveScene().name=="SampleScene"&&!WorldSession.Instance.Busy,"retorno real à cidade conclui");
 }
 void Capture(string name){ScreenCapture.CaptureScreenshot("Docs/Validacao9/"+name+".png");}
}


